      name: 'type_tool',
      description: 'types',
      inputSchema: { type: 'object', properties: { count: { type: 'string' } }, required: ['count'] }
    }, async () => 'success');

    const result = await registry.execute('type_tool', { count: 123456789 });
    expect(result).toHaveProperty('result');
    const msg = (result as { result: string }).result;
    expect(msg).toMatch(/count/);
    expect(msg).toMatch(/string/);
    expect(msg).not.toMatch(/123456789/);
  });

  it('throws at registration time for an uncompilable schema, and message names the tool', () => {
    const registry = new ToolRegistry();
    expect(() => {
      registry.register({
        name: 'bad_schema_tool',
        description: 'bad',
        inputSchema: { type: 'invalid_type_here' } as any
      }, async () => 'success');
    }).toThrow(/bad_schema_tool/);
  });

  it('validates a function-valued definition against the schema current at that call, not a stale cached one', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    let schemaType = 'string';
    registry.register(() => ({
      name: 'dynamic_tool',
      description: 'dyn',
      inputSchema: { type: 'object', properties: { prop: { type: schemaType } }, required: ['prop'] }
    }), async () => { calls++; return 'success'; });

    // First call: prop must be a string
    const res1 = await registry.execute('dynamic_tool', { prop: 'text' });
    expect(calls).toBe(1);

    // Second call: change schema to require a number
    schemaType = 'number';
    const res2 = await registry.execute('dynamic_tool', { prop: 'text' });
    expect(calls).toBe(1); // should fail validation
    expect(res2).toHaveProperty('result');
    expect((res2 as any).result).toMatch(/number/);
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let accesses = 0;
    const inputSchema = {
      get type() { accesses++; return 'object'; },
      properties: { val: { type: 'string' } }
    };
    registry.register({
      name: 'static_tool',
      description: 'static',
      inputSchema
    }, async () => 'success');

    const accessCountAfterRegister = accesses;
    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {}); // it might fail validation, that's fine
    }
    // accesses should not grow by 10 if compiled once. It might be 1 if it accesses at compilation, 
    // or same as before register, but it should not be accessCountAfterRegister + 10
    expect(accesses).toBeLessThan(accessCountAfterRegister + 10);
  });

  it('still throws Unknown tool: <name> for an unregistered name, unchanged', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });

  it('produces no log line containing an identifying field value when payload is rejected', async () => {
    const registry = new ToolRegistry();
    registry.register({
      name: 'secret_tool',
      description: 'secret',
      inputSchema: { type: 'object', properties: { secret_field: { type: 'number' } }, required: ['secret_field'] }
