describe('chatOrchestrator validation loop', () => {
  it('drives a stub provider through a rejected tool call followed by a corrected retry, and processMessage resolves with rejection visible', async () => {
    let callCount = 0;
    let textSeenByProviderOnRoundTwo: string | undefined;

    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        callCount++;
        if (callCount === 1) {
          // Round 1: provider makes a tool call with bad input
          yield { type: 'tool_use', toolCall: { id: 'call_1', name: 'location_tool', input: { wrong_field: 123 } } };
          yield { type: 'stop', stopReason: 'tool_use' };
        } else {
          // Round 2: check what the provider was sent
          const lastMessage = params.messages[params.messages.length - 1];
          if (lastMessage.role === 'user' && typeof lastMessage.content !== 'string' && lastMessage.content[0].type === 'tool_result') {
            textSeenByProviderOnRoundTwo = lastMessage.content[0].content;
          }
          yield { type: 'text', text: 'got it' };
          yield { type: 'stop', stopReason: 'end_turn' };
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const registry = new ToolRegistry();
    registry.register({
      name: 'location_tool',
      description: 'gets location',
      inputSchema: { type: 'object', properties: { location: { type: 'string' } }, required: ['location'] }
    }, async () => 'success');

    const orchestrator = createChatOrchestrator(provider, new PromptBuilder(), registry);

    await expect(orchestrator.processMessage(createSession('hello'))).resolves.toBeUndefined();
    expect(callCount).toBe(2);
    // Provider should have seen the rejection text about the missing 'location'
    expect(textSeenByProviderOnRoundTwo).toMatch(/location/);
  });
});

